from collections import deque

def find_components(grid, target_val):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    visited = set()
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == target_val and (r, c) not in visited:
                # BFS to find connected component
                component = set()
                queue = deque([(r, c)])
                visited.add((r, c))

                while queue:
                    cr, cc = queue.popleft()
                    component.add((cr, cc))

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if (nr, nc) not in visited and grid[nr][nc] == target_val:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
                components.append(component)

    return components

