# Let me implement a BFS from input 2s, traveling through 0s only (not 1s)
from collections import deque

def transform_with_bfs_through_0s_only(grid):
    if not grid:
        return grid
    rows, cols = len(grid), len(grid[0])

    # Make a copy
    result = [row[:] for row in grid]

    # Find all input 2s
    input_2s = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 2]

    # BFS from each input 2, only through 0s (not 1s)
    # We're on a 2, and we can spread to adjacent 0s, which then become 2s and can spread further
    all_reachable_2s = set(input_2s)  # Start with all input 2s
    queue = list(input_2s)

    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == 0 and (nr, nc) not in all_reachable_2s:
                    all_reachable_2s.add((nr, nc))
                    result[nr][nc] = 2
                    queue.append((nr, nc))

    return result

